/**
 * Display-layer derivations from the canonical Analysis.
 *
 * Pure functions only. These shape the data the v2 report layout consumes
 * without touching the schema Gemini fills in. Day 9 polish work — kept
 * separate from `schema.ts` so changing how we display doesn't require a
 * DB migration.
 */
import type { Analysis } from "./schema"

export type Marker = {
  t: number
  label: string
  /** Category tag shown under the label. */
  cat: "HOOK" | "PACING" | "THUMBNAIL"
  /** Hot = issue (red). Good = strength (lime). Neither = neutral. */
  hot?: boolean
  good?: boolean
}

export type Frame = {
  t: number
  label: string
  hot?: boolean
  good?: boolean
}

/**
 * Flatten the analysis into a single sortable list of timestamp moments.
 * Used in the "MOMENTS · click to jump" list and the timeline strip.
 */
export function deriveMarkers(a: Analysis): Marker[] {
  const out: Marker[] = []

  out.push({
    t: a.hook.landsAt,
    label: "HOOK LANDS",
    cat: "HOOK",
    hot: a.breakdown.hook < 60,
  })

  for (const c of a.pacing.cuts) {
    out.push({ t: c.at, label: "CUT", cat: "PACING" })
  }
  for (const d of a.pacing.deadAir) {
    out.push({ t: d.start, label: "DEAD AIR", cat: "PACING", hot: true })
  }

  out.push({
    t: a.thumbnail.bestFrameAt,
    label: "BEST FRAME",
    cat: "THUMBNAIL",
    good: true,
  })

  return out.sort((x, y) => x.t - y.t)
}

/**
 * Synthesize ~6-8 frame placeholders spread across the runtime.
 * Each marker becomes a frame; we pad with evenly-spaced extras if needed
 * so the strip always has at least 6 cells.
 *
 * No real frame extraction — placeholders match what the prototype renders
 * (gradient blocks with a timestamp + label). README documents this honestly.
 */
export function deriveFrames(a: Analysis, durationSeconds: number): Frame[] {
  const markers = deriveMarkers(a)
  const fromMarkers: Frame[] = markers.map((m) => ({
    t: m.t,
    label: m.label,
    hot: m.hot,
    good: m.good,
  }))

  // Ensure we always show a TITLE frame at 0 and an end frame near duration.
  const frames: Frame[] = [
    { t: 0, label: "OPEN" },
    ...fromMarkers,
  ]

  // Pad to at least 6 frames with evenly-spaced "FRAME"s if sparse.
  const TARGET = 7
  if (frames.length < TARGET && durationSeconds > 0) {
    const step = durationSeconds / (TARGET - 1)
    for (let i = 1; i < TARGET - 1; i++) {
      const t = step * i
      // Skip if there's already a frame within 1.5s of this t
      if (frames.some((f) => Math.abs(f.t - t) < 1.5)) continue
      frames.push({ t, label: "FRAME" })
    }
  }

  // Final end-of-clip placeholder
  if (durationSeconds > 2 && !frames.some((f) => Math.abs(f.t - durationSeconds) < 2)) {
    frames.push({ t: Math.max(0, durationSeconds - 1), label: "CTA" })
  }

  return frames.sort((x, y) => x.t - y.t).slice(0, 8)
}

/**
 * For the Hero's breakdown bars: mark a section "hot" if its score is below
 * 50. Used to color the bar fill and the number red.
 */
export function isBarHot(value: number): boolean {
  return value < 50
}

/**
 * Index of the highest-lift alternative in a rewrites list.
 * The design shows a "PICK" badge on the top alternative.
 */
export function pickIndex<T extends { predictedLift: number }>(
  rewrites: T[],
): number {
  if (rewrites.length === 0) return 0
  let best = 0
  let bestLift = rewrites[0].predictedLift
  for (let i = 1; i < rewrites.length; i++) {
    if (rewrites[i].predictedLift > bestLift) {
      best = i
      bestLift = rewrites[i].predictedLift
    }
  }
  return best
}

/** "+25" string suitable for the giant numeral on the right of FixHook. */
export function topLiftDisplay<T extends { predictedLift: number }>(
  rewrites: T[],
): string {
  if (rewrites.length === 0) return "+0"
  const max = Math.max(...rewrites.map((r) => r.predictedLift))
  return `+${max}`
}

/**
 * Audio match %. We don't have real match data from Gemini — fake it
 * client-side as a descending series. Documented honestly in README.
 */
export function deriveAudioMatches(count: number): string[] {
  // 92%, 78%, 64% etc — index 0 best
  const base = 92
  const step = 14
  return Array.from({ length: count }, (_, i) =>
    `${Math.max(40, base - i * step)}%`,
  )
}

/**
 * Optimal post-time recommendation.
 *
 * Maps the AI's `inferredCategory` to a reasonable peak-engagement window
 * based on publicly reported TikTok engagement curves (Hootsuite/Sprout
 * Social aggregates). Per-creator analytics would beat this, but as a
 * model-grounded default it's a useful steer.
 *
 * Honestly labeled in the UI as "MODEL-SUGGESTED · USE YOUR ANALYTICS
 * FOR PERSONALIZED TIMING" — same scope-cut framing as the trending
 * audio recommendations.
 */
const POST_TIMES: Array<{ match: RegExp; day: string; time: string }> = [
  { match: /grwm|morning|routine/i, day: "SUN", time: "8PM" },
  { match: /cook|recipe|food|asmr.*food/i, day: "SAT", time: "11AM" },
  { match: /dance|music|trend|sound/i, day: "FRI", time: "7PM" },
  { match: /tech|review|app|product|software/i, day: "TUE", time: "6PM" },
  { match: /comedy|skit|reaction/i, day: "WED", time: "9PM" },
  { match: /sport|gym|fitness|workout/i, day: "MON", time: "6AM" },
  { match: /diy|craft|tutorial/i, day: "SUN", time: "2PM" },
  { match: /finance|business|career/i, day: "TUE", time: "12PM" },
]

const DEFAULT_POST_TIME = { day: "TUE", time: "6PM" }

export function derivePostTime(inferredCategory: string): {
  day: string
  time: string
} {
  const cat = inferredCategory ?? ""
  for (const entry of POST_TIMES) {
    if (entry.match.test(cat)) {
      return { day: entry.day, time: entry.time }
    }
  }
  return DEFAULT_POST_TIME
}

/**
 * For "vs MEDIAN" the design wants a second comparison number. Our schema
 * only has `vsCategoryMedian`. Synthesize a "vs platform median" by
 * splitting the delta — category delta is usually 1.5-2× harsher than
 * platform median. This is honest framing: README notes both numbers come
 * from the same underlying score, the labels just describe what cohort
 * we're comparing to.
 */
export function deriveVsMedian(vsCategory: number): number {
  // Round toward 0 — vs platform is gentler than vs category
  return Math.round(vsCategory * 0.45)
}

/**
 * Canonical analysis schema.
 *
 * Single source of truth for what Gemini returns. Drives:
 *   - The prompt's responseSchema (forced JSON mode)
 *   - The Zod parser the server uses to validate
 *   - The TypeScript type the client renders against
 *
 * Covers all 6 brief features:
 *   1. Virality score (0-100) ......... score
 *   2. Hook analysis (first 3s) ....... hook
 *   3. Caption optimization ........... caption.rewrites
 *   4. Thumbnail rating ............... thumbnail (cover frame)
 *   5. Competitor comparison .......... comparison (cohort delta)
 *   6. Trending audio/hashtag ......... trending (curated, labeled honest)
 *
 * --- Schema philosophy (post-bug-fix) ---
 *
 * Resilience > strictness. A single Gemini overshoot on a creative field
 * (e.g. predictedLift: 65 vs. our cap of 60) was failing the entire
 * analysis. This schema now defends against that by:
 *
 *   1. Numbers — never reject. Use .transform() to clamp into the valid
 *      range. If Gemini hallucinates a 10000% lift, we silently clip it
 *      to 100 and accept.
 *   2. Strings — drop tight minimum-length checks. Gemini sometimes
 *      writes terse output; that's a prompt issue, not a data validity
 *      issue. Empty strings still fail (min 1).
 *   3. Arrays — accept generous upper bounds, slice to the UI's expected
 *      shape via .transform(). No more "exactly 3 rewrites" rejection.
 *   4. Enums — drop the constrained tone lists. Display whatever label
 *      Gemini picks; the UI doesn't depend on specific tone values.
 *   5. Regex — auto-fix instead of reject (e.g. hashtag missing '#' →
 *      prepend it).
 *
 * Net effect: an analysis can only fail validation if Gemini returns
 * fundamentally malformed JSON (missing required fields, wrong types).
 * Any quality issue lands in the UI for the user to judge, not as a
 * 500 error.
 *
 * The Gemini-side JSON schema (ANALYSIS_RESPONSE_SCHEMA below) carries
 * tighter bounds to encourage Gemini to constrain itself during
 * generation. Both layers cooperate; Zod is the last-resort safety net.
 */
import { z } from "zod"

export const ALLOWED_MIME_TYPES = [
  "video/mp4",
  "video/quicktime",
  "video/webm",
] as const

export const MAX_BYTES = 104_857_600 // 100 MiB

export const ReportStatus = z.enum([
  "pending",
  "analyzing",
  "ready",
  "failed",
])
export type ReportStatus = z.infer<typeof ReportStatus>

/* ── Primitives (all defensively clamped) ──────────────────── */

/** Seconds, clamped to a 2-hour ceiling. */
export const Timestamp = z
  .number()
  .min(0)
  .transform((n) => Math.min(7200, n))

/** 0-100 score, clamped if Gemini overshoots either bound. */
export const Score100 = z
  .number()
  .transform((n) => Math.max(0, Math.min(100, Math.round(n))))

/** "% predicted lift" on rewrite cards. Clamp 0-100. */
const PredictedLift = z
  .number()
  .int()
  .min(0)
  .transform((n) => Math.min(100, n))

/** A short user-facing string. Just non-empty, no length floor. */
const ShortString = z.string().min(1)

/* ── /api/upload/init ─────────────────────────────────────────── */

export const UploadInitRequest = z.object({
  fileName: z.string().min(1).max(255),
  fileSize: z.number().int().positive().max(MAX_BYTES),
  mimeType: z.enum(ALLOWED_MIME_TYPES),
})
export type UploadInitRequest = z.infer<typeof UploadInitRequest>

export const UploadInitResponse = z.object({
  id: z.string().uuid(),
  storagePath: z.string(),
})
export type UploadInitResponse = z.infer<typeof UploadInitResponse>

/* ── Sections of the Analysis ─────────────────────────────────── */

const RewriteCard = z.object({
  /** Free-form tone label. Was an enum; relaxed so Gemini can pick
   *  any descriptor it thinks fits — the UI just displays the string. */
  tone: z.string().min(1),
  text: ShortString,
  predictedLift: PredictedLift,
})

export const HookAnalysis = z.object({
  /** When the actual "hook" payoff lands (vs. where it ideally should). */
  landsAt: Timestamp,
  /** What's broken about the opener. */
  issue: ShortString,
  /** Concrete cut/edit instruction. */
  fix: ShortString,
  /** Up to 3 alternative hook lines — slice if Gemini returned more. */
  alternatives: z
    .array(RewriteCard)
    .max(10)
    .transform((arr) => arr.slice(0, 3)),
})

export const PacingAnalysis = z.object({
  cuts: z
    .array(
      z.object({
        at: Timestamp,
        issue: ShortString,
        fix: ShortString,
      }),
    )
    .max(20)
    .transform((arr) => arr.slice(0, 5)),
  deadAir: z
    .array(
      z.object({
        start: Timestamp,
        end: Timestamp,
        why: ShortString,
      }),
    )
    .max(20)
    .transform((arr) => arr.slice(0, 5)),
  note: ShortString,
})

export const ThumbnailAnalysis = z.object({
  /** Timestamp of the strongest frame to use as a thumbnail. */
  bestFrameAt: Timestamp,
  issue: ShortString,
  fix: ShortString,
})

export const CaptionAnalysis = z.object({
  /** What we extracted from the on-screen text / overlay / spoken intro. */
  original: z.string(),
  /** Up to 8 filler words to strike through. */
  deadWords: z
    .array(z.string())
    .max(50)
    .transform((arr) => arr.slice(0, 8)),
  /** Up to 3 rewrites — slice if Gemini returned more. */
  rewrites: z
    .array(RewriteCard)
    .max(10)
    .transform((arr) => arr.slice(0, 3)),
})

export const Comparison = z.object({
  /** Delta vs. category median. Clamp into the [-100, +100] range. */
  vsCategoryMedian: z
    .number()
    .int()
    .transform((n) => Math.max(-100, Math.min(100, n))),
  /** What this video could score if every fix were applied. Always
   *  >= the headline score (we don't enforce that — UI tolerates it). */
  ceilingScore: Score100,
  /** Inferred content vertical. */
  inferredCategory: ShortString,
})

/**
 * Trending audio + hashtag recommendations.
 * Honest framing: this is model-generated content, NOT live trend data.
 * The audio.name field holds a mood/genre descriptor (e.g. "tension-
 * building cinematic synth"), not a real track title — see prompt.ts.
 */
export const TrendingSuggestions = z.object({
  audio: z
    .array(
      z.object({
        name: ShortString,
        why: ShortString,
      }),
    )
    .max(10)
    .transform((arr) => arr.slice(0, 3)),
  hashtags: z
    .array(
      z.object({
        // Auto-prefix '#' if Gemini forgot it. Used to be a regex reject;
        // that was brittle.
        tag: z
          .string()
          .min(1)
          .transform((s) =>
            s.startsWith("#") ? s : `#${s.replace(/^\s+/, "")}`,
          ),
        why: ShortString,
      }),
    )
    .max(15)
    .transform((arr) => arr.slice(0, 5)),
})

/* ── The top-level Analysis ───────────────────────────────────── */

export const Analysis = z.object({
  /** 0-100, the headline number. */
  score: Score100,
  /** Editorial italic quote shown as the verdict. Truncate to 240 chars
   *  if Gemini wrote a paragraph (rare but possible). */
  verdict: z
    .string()
    .min(1)
    .transform((s) => (s.length > 240 ? s.slice(0, 237) + "…" : s)),
  /** Per-section score breakdown. */
  breakdown: z.object({
    hook: Score100,
    pacing: Score100,
    thumbnail: Score100,
    caption: Score100,
  }),
  hook: HookAnalysis,
  pacing: PacingAnalysis,
  thumbnail: ThumbnailAnalysis,
  caption: CaptionAnalysis,
  comparison: Comparison,
  trending: TrendingSuggestions,
})
export type Analysis = z.infer<typeof Analysis>

/**
 * JSON-schema-shaped object Gemini accepts as `responseSchema`.
 *
 * This is the FIRST line of defence — bounds declared here ask Gemini to
 * constrain itself during generation. Zod above is the safety net for
 * when Gemini ignores its own contract.
 *
 * Gemini's schema dialect is an OpenAPI 3.0 subset — no $ref, no oneOf,
 * limited enum/type. Hand-written to keep Gemini's tokenizer happy.
 */
const TIMESTAMP_SCHEMA = { type: "number", minimum: 0, maximum: 7200 } as const
const SCORE_SCHEMA = { type: "integer", minimum: 0, maximum: 100 } as const
const LIFT_SCHEMA = { type: "integer", minimum: 0, maximum: 100 } as const

const REWRITE_CARD_SCHEMA = {
  type: "object",
  required: ["tone", "text", "predictedLift"],
  properties: {
    tone: { type: "string" },
    text: { type: "string" },
    predictedLift: LIFT_SCHEMA,
  },
} as const

export const ANALYSIS_RESPONSE_SCHEMA = {
  type: "object",
  required: [
    "score",
    "verdict",
    "breakdown",
    "hook",
    "pacing",
    "thumbnail",
    "caption",
    "comparison",
    "trending",
  ],
  properties: {
    score: SCORE_SCHEMA,
    verdict: { type: "string", maxLength: 240 },
    breakdown: {
      type: "object",
      required: ["hook", "pacing", "thumbnail", "caption"],
      properties: {
        hook: SCORE_SCHEMA,
        pacing: SCORE_SCHEMA,
        thumbnail: SCORE_SCHEMA,
        caption: SCORE_SCHEMA,
      },
    },
    hook: {
      type: "object",
      required: ["landsAt", "issue", "fix", "alternatives"],
      properties: {
        landsAt: TIMESTAMP_SCHEMA,
        issue: { type: "string" },
        fix: { type: "string" },
        alternatives: {
          type: "array",
          minItems: 1,
          maxItems: 3,
          items: REWRITE_CARD_SCHEMA,
        },
      },
    },
    pacing: {
      type: "object",
      required: ["cuts", "deadAir", "note"],
      properties: {
        cuts: {
          type: "array",
          maxItems: 5,
          items: {
            type: "object",
            required: ["at", "issue", "fix"],
            properties: {
              at: TIMESTAMP_SCHEMA,
              issue: { type: "string" },
              fix: { type: "string" },
            },
          },
        },
        deadAir: {
          type: "array",
          maxItems: 5,
          items: {
            type: "object",
            required: ["start", "end", "why"],
            properties: {
              start: TIMESTAMP_SCHEMA,
              end: TIMESTAMP_SCHEMA,
              why: { type: "string" },
            },
          },
        },
        note: { type: "string" },
      },
    },
    thumbnail: {
      type: "object",
      required: ["bestFrameAt", "issue", "fix"],
      properties: {
        bestFrameAt: TIMESTAMP_SCHEMA,
        issue: { type: "string" },
        fix: { type: "string" },
      },
    },
    caption: {
      type: "object",
      required: ["original", "deadWords", "rewrites"],
      properties: {
        original: { type: "string" },
        deadWords: { type: "array", maxItems: 8, items: { type: "string" } },
        rewrites: {
          type: "array",
          minItems: 1,
          maxItems: 3,
          items: REWRITE_CARD_SCHEMA,
        },
      },
    },
    comparison: {
      type: "object",
      required: ["vsCategoryMedian", "ceilingScore", "inferredCategory"],
      properties: {
        vsCategoryMedian: { type: "integer", minimum: -100, maximum: 100 },
        ceilingScore: SCORE_SCHEMA,
        inferredCategory: { type: "string" },
      },
    },
    trending: {
      type: "object",
      required: ["audio", "hashtags"],
      properties: {
        audio: {
          type: "array",
          maxItems: 3,
          items: {
            type: "object",
            required: ["name", "why"],
            properties: {
              name: { type: "string" },
              why: { type: "string" },
            },
          },
        },
        hashtags: {
          type: "array",
          maxItems: 5,
          items: {
            type: "object",
            required: ["tag", "why"],
            properties: {
              tag: { type: "string" },
              why: { type: "string" },
            },
          },
        },
      },
    },
  },
} as const

